package com.steven.assets.bff.portfolioadvice;
import com.steven.assets.bff.security.*;import org.junit.jupiter.api.*;import org.springframework.mock.http.server.reactive.MockServerHttpRequest;import org.springframework.mock.web.server.MockServerWebExchange;import org.springframework.mock.web.server.MockWebSession;import org.springframework.http.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.core.oidc.OidcIdToken;import org.springframework.security.oauth2.core.oidc.user.*;import org.springframework.web.reactive.function.client.*;import reactor.core.publisher.Mono;import java.util.*;import java.util.concurrent.atomic.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class SrppClaudeAuthBffServiceTest {
 BusinessUserClient users;SrppClaudeAuthBffService service;AtomicInteger calls;AtomicReference<ClientRequest> sent;String reply;MockWebSession session;
 OidcUser principal(boolean configured,String role,String status){var a=new ArrayList<SimpleGrantedAuthority>();a.add(new SimpleGrantedAuthority("APP_UID_7"));a.add(new SimpleGrantedAuthority("APP_STATUS_"+status));a.add(new SimpleGrantedAuthority("ROLE_"+role));if(configured)a.add(new SimpleGrantedAuthority(AuthConstants.AUTHORITY_CONFIGURED_ADMIN));return new DefaultOidcUser(a,OidcIdToken.withTokenValue("synthetic").claim("sub","7").build());}
 @BeforeEach void setup(){users=mock(BusinessUserClient.class);when(users.configuredAdmin()).thenReturn(Mono.just(new BffUser(7L,"admin@example.test",null,null,"ADMIN","ACTIVE",true)));calls=new AtomicInteger();sent=new AtomicReference<>();reply="{\"schemaVersion\":1,\"toolId\":\"claude\",\"loginState\":\"VALID\",\"expiresAt\":\"2099-11-16T00:00:00Z\",\"code\":null}";WebClient client=WebClient.builder().filter((req,next)->Mono.deferContextual(ctx->{assertThat(ctx.hasKey(AuthConstants.CTX_IDENTITY)).isFalse();return next.exchange(req);})).exchangeFunction(req->{calls.incrementAndGet();sent.set(req);return Mono.just(ClientResponse.create(HttpStatus.OK).header("Content-Type","application/json").body(reply).build());}).build();service=new SrppClaudeAuthBffService(users,client);session=new MockWebSession();}
 MockServerWebExchange exchange(boolean post,String origin,String nonce,String effective){var b=post?MockServerHttpRequest.post("https://asset-management.asuscomm.com/api/bff/portfolio-advice/srpp/ai-auth/claude/start"):MockServerHttpRequest.get("https://asset-management.asuscomm.com/api/bff/portfolio-advice/srpp/ai-auth/claude/state");b.header(AuthConstants.HDR_USER_ID,effective);if(origin!=null)b.header("Origin",origin);if(nonce!=null)b.header("X-SRPP-AI-Auth-CSRF",nonce);if(post)b.header("Content-Type","application/json");return MockServerWebExchange.builder(b).session(session).build();}
 @Test void realConfiguredAdminBootstrapSetsPrivateRandomBindingAndUsesSelfHeaders(){Object v=service.call(exchange(false,null,null,"7"),principal(true,"ADMIN","ACTIVE"),"state","claude",null,null).contextWrite(ctx->ctx.put(AuthConstants.CTX_IDENTITY,new TenantIdentity(99L,"ADMIN","ACTIVE"))).block();assertThat(v).isInstanceOf(SrppClaudeAuthDto.BootstrapResponse.class);var boot=(SrppClaudeAuthDto.BootstrapResponse)v;assertThat(boot.csrfToken()).matches("[A-Za-z0-9_-]{43}");assertThat((String)session.getAttribute(SrppClaudeAuthBffService.BINDING)).matches("[A-Za-z0-9_-]{43}").isNotEqualTo(boot.csrfToken());assertThat(sent.get().headers().getFirst(AuthConstants.HDR_USER_ID)).isEqualTo("7");assertThat(sent.get().headers().getFirst("X-SRPP-AI-Auth-Binding")).isEqualTo(session.getAttribute(SrppClaudeAuthBffService.BINDING));assertThat(boot.toString()).doesNotContain(boot.csrfToken());}
 @Test void userOtherAdminInactiveAndImpersonatingRejectBeforeFreshLookupAndHost(){for(OidcUser p:List.of(principal(false,"USER","ACTIVE"),principal(false,"ADMIN","ACTIVE"),principal(true,"ADMIN","DISABLED"))){assertThatThrownBy(()->service.call(exchange(false,null,null,"7"),p,"state","claude",null,null).block()).isInstanceOf(SrppClaudeAuthProblem.class);}assertThatThrownBy(()->service.call(exchange(false,null,null,"8"),principal(true,"ADMIN","ACTIVE"),"state","claude",null,null).block()).isInstanceOf(SrppClaudeAuthProblem.class);verifyNoInteractions(users);assertThat(calls.get()).isZero();}
 @Test void postMissingNonceWrongOriginAndCrossSessionRejectBeforeAuthority(){session.getAttributes().put(SrppClaudeAuthBffService.NONCE,"n".repeat(43));session.getAttributes().put(SrppClaudeAuthBffService.BINDING,"b".repeat(43));for(String origin:List.of("https://evil.test","https://asset-management.asuscomm.com.evil.test","null","https://asset-management.asuscomm.com/path"))assertThatThrownBy(()->service.call(exchange(true,origin,"n".repeat(43),"7"),principal(true,"ADMIN","ACTIVE"),"start",null,null,"{\"toolId\":\"claude\"}").block()).isInstanceOf(SrppClaudeAuthProblem.class);assertThatThrownBy(()->service.call(exchange(true,"https://asset-management.asuscomm.com",null,"7"),principal(true,"ADMIN","ACTIVE"),"start",null,null,"{}").block()).isInstanceOf(SrppClaudeAuthProblem.class);session=new MockWebSession();assertThatThrownBy(()->service.call(exchange(true,"https://asset-management.asuscomm.com","n".repeat(43),"7"),principal(true,"ADMIN","ACTIVE"),"start",null,null,"{}").block()).isInstanceOf(SrppClaudeAuthProblem.class);verifyNoInteractions(users);assertThat(calls.get()).isZero();}
 @Test void freshConfiguredAdminMismatchRejectsAndNeverUsesCachedAuthority(){when(users.configuredAdmin()).thenReturn(Mono.just(new BffUser(8L,null,null,null,"ADMIN","ACTIVE",true)));assertThatThrownBy(()->service.call(exchange(false,null,null,"7"),principal(true,"ADMIN","ACTIVE"),"state","claude",null,null).block()).isInstanceOf(SrppClaudeAuthProblem.class);assertThat(calls.get()).isZero();}
 @Test void validPostUsesExistingSessionAndClosedFields(){service.call(exchange(false,null,null,"7"),principal(true,"ADMIN","ACTIVE"),"state","claude",null,null).block();String nonce=session.getAttribute(SrppClaudeAuthBffService.NONCE);reply="{\"schemaVersion\":1,\"flowId\":\""+"f".repeat(43)+"\",\"toolId\":\"claude\",\"status\":\"CANCELLED\",\"authorizationUrl\":null,\"expiresAt\":\"2026-11-16T00:00:00Z\",\"code\":null}";Object response=service.call(exchange(true,"https://asset-management.asuscomm.com",nonce,"7"),principal(true,"ADMIN","ACTIVE"),"cancel",null,"f".repeat(43),"{}").block();assertThat(response).isInstanceOf(SrppClaudeAuthDto.AuthFlow.class);assertThat(calls.get()).isEqualTo(2);assertThat(sent.get().url().getPath()).endsWith("/cancel");assertThatThrownBy(()->service.call(exchange(true,"https://asset-management.asuscomm.com",nonce,"7"),principal(true,"ADMIN","ACTIVE"),"start",null,null,"{\"toolId\":\"claude\",\"ownerId\":8}").block()).isInstanceOf(SrppClaudeAuthProblem.class);assertThat(calls.get()).isEqualTo(2);}
 @Test void adviceNeverExposesNativeCodeUrlOrRequest(){var response=new SrppClaudeAuthExceptionAdvice().failure(new IllegalArgumentException("SECRET_CODE https://claude.com/private"));assertThat(response.getHeaders().getCacheControl()).isEqualTo("no-store");assertThat(response.getBody().message()).doesNotContain("SECRET_CODE","https://");assertThat(response.getBody().code()).isEqualTo("AUTH_FAILED");}
}
